// 從前一個節點取得參數
const slackChannel = $input.first().json.slack_channel;
const expectedReportersStr = $input.first().json.expected_reporters;
const expectedReporterIds = expectedReportersStr.split(',');

// 取得今天日期 (台北時區)
const today = new Date();
const taipeiOffset = 8 * 60; // UTC+8
const taipeiTime = new Date(today.getTime() + (taipeiOffset + today.getTimezoneOffset()) * 60000);
const year = taipeiTime.getFullYear();
const month = String(taipeiTime.getMonth() + 1).padStart(2, '0');
const day = String(taipeiTime.getDate()).padStart(2, '0');
const todayStr = `${year}-${month}-${day}`;

// 計算搜尋時間範圍 (今天 00:00 到現在)
const startOfDay = new Date(taipeiTime);
startOfDay.setHours(0, 0, 0, 0);
const oldestTimestamp = Math.floor((startOfDay.getTime() - taipeiOffset * 60000) / 1000);

// 使用 Slack API 取得頻道訊息
const slackToken = $credentials.slackApi.accessToken;

try {
  const response = await fetch(`https://slack.com/api/conversations.history?channel=${slackChannel}&oldest=${oldestTimestamp}&limit=200`, {
    headers: {
      'Authorization': `Bearer ${slackToken}`,
      'Content-Type': 'application/json'
    }
  });

  const data = await response.json();

  if (!data.ok) {
    throw new Error(`Slack API error: ${data.error}`);
  }

  const messages = data.messages || [];

  // 找出今天有發送訊息的用戶
  const reportedUsers = new Set();
  for (const msg of messages) {
    if (msg.user) {
      reportedUsers.add(msg.user);
    }
  }

  // 找出未回報的用戶
  const missingReporters = expectedReporterIds.filter(id => !reportedUsers.has(id));

  // 準備輸出
  const result = {
    date: todayStr,
    total_expected: expectedReporterIds.length,
    total_reported: expectedReporterIds.length - missingReporters.length,
    missing_count: missingReporters.length,
    missing_reporters: missingReporters,
    slack_channel: slackChannel,
    has_missing: missingReporters.length > 0
  };

  return [{ json: result }];

} catch (error) {
  return [{
    json: {
      error: true,
      message: error.message,
      date: todayStr
    }
  }];
}

